CREATE VIEW v_cards_sets AS SELECT cards.id AS card_id, cards.name AS card_name, cards.asciiName AS ascii_name, cards.uuid, cards.artist, cards.borderColor AS border_color, cards.colors, cards.convertedManaCost AS converted_mana_cost, cards.faceName AS face_name, cards.flavorText AS flavor_text, cards.keywords, cards.layout, cards.manaCost AS mana_cost, cards.power, cards.rarity, cards.setCode AS set_code, cards.side, cards.subtypes, cards.supertypes, cards.text AS card_text, cards.toughness, cards.type AS card_type, cards.types, sets.name AS set_name, sets.block AS set_block, sets.releaseDate AS set_release_date, sets.totalSetSize AS total_set_size, sets.type AS set_type, cards.availability, cards.cardKingdomFoilId, cards.cardKingdomId, cards.colorIdentity, cards.colorIndicator, cards.duelDeck, cards.edhrecRank, cards.faceConvertedManaCost, cards.flavorName, cards.frameEffects, cards.frameVersion, cards.hand, cards.hasAlternativeDeckLimit, cards.hasContentWarning, cards.hasFoil, cards.hasNonFoil, cards.isAlternative, cards.isFullArt, cards.isOnlineOnly, cards.isOversized, cards.isPromo, cards.isReprint, cards.isReserved, cards.isStarter, cards.isStorySpotlight, cards.isTextless, cards.isTimeshifted, cards.leadershipSkills, cards.life, cards.loyalty, cards.mcmId, cards.mcmMetaId, cards.mtgArenaId, cards.mtgjsonV4Id, cards.mtgoFoilId, cards.mtgoId, cards.multiverseId, cards.number, cards.originalReleaseDate, cards.originalText, cards.originalType, cards.otherFaceIds, cards.printings, cards.promoTypes, cards.purchaseUrls, cards.scryfallId, cards.scryfallIllustrationId, cards.scryfallOracleId, cards.tcgplayerProductId, cards.variations, cards.watermark, sets.id, sets.baseSetSize, sets.booster, sets.code, sets.isFoilOnly, sets.isForeignOnly, sets.isNonFoilOnly, sets.isOnlineOnly AS sets_isOnlineOnly, sets.isPartialPreview, sets.keyruneCode, sets.mcmId AS sets_mcmId, sets.mcmIdExtras, sets.mcmName, sets.mtgoCode, sets.parentCode, sets.tcgplayerGroupId FROM cards LEFT JOIN sets ON cards.setCode = sets.code;

CREATE VIEW v_cards_legalities AS SELECT cards.id AS card_id, cards.name AS card_name, cards.uuid, cards.setCode AS set_code, cards.type AS card_type, cards.rarity, legalities.format AS legality_format, legalities.status AS legality_status, cards.artist, cards.asciiName, cards.availability, cards.borderColor, cards.cardKingdomFoilId, cards.cardKingdomId, cards.colorIdentity, cards.colorIndicator, cards.colors, cards.convertedManaCost, cards.duelDeck, cards.edhrecRank, cards.faceConvertedManaCost, cards.faceName, cards.flavorName, cards.flavorText, cards.frameEffects, cards.frameVersion, cards.hand, cards.hasAlternativeDeckLimit, cards.hasContentWarning, cards.hasFoil, cards.hasNonFoil, cards.isAlternative, cards.isFullArt, cards.isOnlineOnly, cards.isOversized, cards.isPromo, cards.isReprint, cards.isReserved, cards.isStarter, cards.isStorySpotlight, cards.isTextless, cards.isTimeshifted, cards.keywords, cards.layout, cards.leadershipSkills, cards.life, cards.loyalty, cards.manaCost, cards.mcmId, cards.mcmMetaId, cards.mtgArenaId, cards.mtgjsonV4Id, cards.mtgoFoilId, cards.mtgoId, cards.multiverseId, cards.number, cards.originalReleaseDate, cards.originalText, cards.originalType, cards.otherFaceIds, cards.power, cards.printings, cards.promoTypes, cards.purchaseUrls, cards.scryfallId, cards.scryfallIllustrationId, cards.scryfallOracleId, cards.side, cards.subtypes, cards.supertypes, cards.tcgplayerProductId, cards.text, cards.toughness, cards.types, cards.variations, cards.watermark, legalities.id, legalities.uuid AS legalities_uuid FROM cards LEFT JOIN legalities ON cards.uuid = legalities.uuid;

CREATE VIEW v_set_translations AS SELECT sets.id AS set_id, sets.code AS set_code, sets.name AS set_name, sets.releaseDate AS set_release_date, set_translations.language AS translation_language, set_translations.translation AS set_translation, sets.baseSetSize, sets.block, sets.booster, sets.isFoilOnly, sets.isForeignOnly, sets.isNonFoilOnly, sets.isOnlineOnly, sets.isPartialPreview, sets.keyruneCode, sets.mcmId, sets.mcmIdExtras, sets.mcmName, sets.mtgoCode, sets.parentCode, sets.tcgplayerGroupId, sets.totalSetSize, sets.type, set_translations.id, set_translations.setCode FROM sets LEFT JOIN set_translations ON sets.code = set_translations.setCode;

CREATE VIEW v_foreign_data AS SELECT foreign_data.id, foreign_data.flavorText, foreign_data.language, foreign_data.multiverseid, foreign_data.name, foreign_data.text, foreign_data.type, foreign_data.uuid, cards.id AS cards_id, cards.artist, cards.asciiName, cards.availability, cards.borderColor, cards.cardKingdomFoilId, cards.cardKingdomId, cards.colorIdentity, cards.colorIndicator, cards.colors, cards.convertedManaCost, cards.duelDeck, cards.edhrecRank, cards.faceConvertedManaCost, cards.faceName, cards.flavorName, cards.flavorText AS cards_flavorText, cards.frameEffects, cards.frameVersion, cards.hand, cards.hasAlternativeDeckLimit, cards.hasContentWarning, cards.hasFoil, cards.hasNonFoil, cards.isAlternative, cards.isFullArt, cards.isOnlineOnly, cards.isOversized, cards.isPromo, cards.isReprint, cards.isReserved, cards.isStarter, cards.isStorySpotlight, cards.isTextless, cards.isTimeshifted, cards.keywords, cards.layout, cards.leadershipSkills, cards.life, cards.loyalty, cards.manaCost, cards.mcmId, cards.mcmMetaId, cards.mtgArenaId, cards.mtgjsonV4Id, cards.mtgoFoilId, cards.mtgoId, cards.multiverseId AS cards_multiverseId, cards.name AS cards_name, cards.number, cards.originalReleaseDate, cards.originalText, cards.originalType, cards.otherFaceIds, cards.power, cards.printings, cards.promoTypes, cards.purchaseUrls, cards.rarity, cards.scryfallId, cards.scryfallIllustrationId, cards.scryfallOracleId, cards.setCode, cards.side, cards.subtypes, cards.supertypes, cards.tcgplayerProductId, cards.text AS cards_text, cards.toughness, cards.type AS cards_type, cards.types, cards.uuid AS cards_uuid, cards.variations, cards.watermark FROM foreign_data LEFT JOIN cards ON foreign_data.uuid = cards.uuid;

CREATE VIEW v_rulings AS SELECT rulings.id, rulings.date, rulings.text, rulings.uuid, cards.id AS cards_id, cards.artist, cards.asciiName, cards.availability, cards.borderColor, cards.cardKingdomFoilId, cards.cardKingdomId, cards.colorIdentity, cards.colorIndicator, cards.colors, cards.convertedManaCost, cards.duelDeck, cards.edhrecRank, cards.faceConvertedManaCost, cards.faceName, cards.flavorName, cards.flavorText, cards.frameEffects, cards.frameVersion, cards.hand, cards.hasAlternativeDeckLimit, cards.hasContentWarning, cards.hasFoil, cards.hasNonFoil, cards.isAlternative, cards.isFullArt, cards.isOnlineOnly, cards.isOversized, cards.isPromo, cards.isReprint, cards.isReserved, cards.isStarter, cards.isStorySpotlight, cards.isTextless, cards.isTimeshifted, cards.keywords, cards.layout, cards.leadershipSkills, cards.life, cards.loyalty, cards.manaCost, cards.mcmId, cards.mcmMetaId, cards.mtgArenaId, cards.mtgjsonV4Id, cards.mtgoFoilId, cards.mtgoId, cards.multiverseId, cards.name, cards.number, cards.originalReleaseDate, cards.originalText, cards.originalType, cards.otherFaceIds, cards.power, cards.printings, cards.promoTypes, cards.purchaseUrls, cards.rarity, cards.scryfallId, cards.scryfallIllustrationId, cards.scryfallOracleId, cards.setCode, cards.side, cards.subtypes, cards.supertypes, cards.tcgplayerProductId, cards.text AS cards_text, cards.toughness, cards.type, cards.types, cards.uuid AS cards_uuid, cards.variations, cards.watermark FROM rulings LEFT JOIN cards ON rulings.uuid = cards.uuid;
